<script>
(() => {
 const api='api_jenny_customer_exclusion.php', previewApi='api_jenny_cleanup_preview.php';
 const search=document.getElementById('pfCaSearch'), select=document.getElementById('pfCaCustomer'), message=document.getElementById('pfCaMessage'), summary=document.getElementById('pfCaCustomerSummary'), scope=document.getElementById('pfCaScope'), orders=document.getElementById('pfCaOrders'), archives=document.getElementById('pfCaArchives'), hide=document.getElementById('pfCaHide'), restore=document.getElementById('pfCaRestore'), dialog=document.getElementById('pfCaDialog');
 if(!search||!select||!message||!scope||!orders||!archives||!hide||!restore||!dialog)return;
 let selectedId=0,currentStatus='inactive',archiveManaged=true,csrf=document.querySelector('meta[name="csrf-token"]')?.content||'',ready=false,pendingAction='',archivePreviewToken='';let timer;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const setMessage=(text,kind='')=>{message.className='pf-box'+(kind?' '+kind:'');message.textContent=text;};
 async function jsonFetch(url,options={}){const r=await fetch(url,{credentials:'same-origin',cache:'no-store',...options});let body;try{body=await r.json()}catch{throw new Error(`Server returned unreadable JSON (HTTP ${r.status}).`)}if(!r.ok||body.success!==true)throw new Error(body.error||`Request failed (HTTP ${r.status}).`);return body;}
 async function findCustomer(){clearTimeout(timer);timer=setTimeout(async()=>{select.disabled=true;select.innerHTML='<option value="">Searching…</option>';try{const data=await jsonFetch(`${api}?search=${encodeURIComponent(search.value.trim())}`);select.innerHTML='<option value="">Select Jenny Ferr</option>';for(const c of data.customers||[]){const opt=document.createElement('option');opt.value=String(c.customer_id);opt.textContent=`${c.name} (#${c.customer_id}) — ${c.email}`;select.appendChild(opt);}select.disabled=false;setMessage((data.customers||[]).length?'Select Jenny Ferr to load the live order preview.':'No matching Jenny Ferr account. This temporary archive is restricted to customer ID 25.');}catch(e){select.innerHTML='<option value="">Search unavailable</option>';setMessage(e.message,'error');}},220);}
 async function loadArchiveList(){try{const data=await jsonFetch(`${api}?list=1`);const rows=data.archives||[];archives.innerHTML=`<table class="pf-table"><thead><tr><th>Customer</th><th>Customer ID</th><th>Hidden orders</th><th>Date archived</th><th>Archived by</th><th>Status</th><th>Reference</th><th>Action</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.first_name)} ${esc(r.last_name)}</td><td>${Number(r.customer_id)}</td><td>${r.status==='active'?Number(r.total_orders)||0:0}</td><td>${esc(r.archived_at)}</td><td>${esc(r.archived_by_name||`User #${r.archived_by}`)}</td><td>${esc(r.status)}${r.archive_managed?'':' (managed elsewhere)'}</td><td>${esc(r.archive_reference_id||'—')}</td><td>${Number(r.customer_id)===25&&r.status==='active'&&r.archive_managed?'<button type="button" class="pf-button pf-restore" data-restore="25">Restore</button>':'—'}</td></tr>`).join('')||'<tr><td colspan="8" class="pf-empty">No customers are currently archived.</td></tr>'}</tbody></table>`;archives.querySelectorAll('[data-restore]').forEach(b=>b.addEventListener('click',async()=>{selectedId=25;if(select.value!=='25')select.value='25';if(!ready)await loadPreview();openDialog('restore');}));}catch(e){archives.innerHTML=`<p class="pf-box error">Archive list unavailable: ${esc(e.message)}</p>`;}}
 async function loadPreview(){ready=false;hide.disabled=true;restore.disabled=true;summary.hidden=true;scope.innerHTML='<p class="pf-empty">Loading exact counts…</p>';orders.innerHTML='<p class="pf-empty">Loading orders…</p>';setMessage('Verifying customer ownership and loading current records…');try{const [control,preview]=await Promise.all([jsonFetch(api),jsonFetch(previewApi)]);if(control.customer_id!==25||preview.target?.customer_id!==25||preview.database?.name!=='u618446170_printflow'||!control.preview_token)throw new Error('The live target or database did not match customer ID 25.');csrf=control.csrf_token||csrf;archivePreviewToken=control.preview_token;currentStatus=control.exclusion?.status||'inactive';archiveManaged=control.archive_managed!==false;const c=control.customer||{};summary.hidden=false;summary.innerHTML=`<strong>${esc(c.first_name)} ${esc(c.last_name)} (#${control.customer_id})</strong> · ${esc(c.email||'')} · ${Number(control.orders_currently_owned)||0} orders · Archive status: <span class="pf-chip">${esc(currentStatus==='active'?'Archived':'Visible')}${archiveManaged?'':' · managed elsewhere'}</span>${control.archive_reference_id?` · Reference: <code>${esc(control.archive_reference_id)}</code>`:''}`;
 const groups=Object.entries(preview.records||{});scope.innerHTML=`<table class="pf-table"><thead><tr><th>Record group</th><th>Count</th><th>Disposition</th></tr></thead><tbody>${groups.map(([name,item])=>`<tr><td>${esc(name)}</td><td>${Number(item.count)||0}</td><td>Hidden from views; source retained (${esc(item.classification||'classified by live preview')})</td></tr>`).join('')||'<tr><td colspan="3">No related record counts returned.</td></tr>'}</tbody></table>`;
 const rows=control.orders||[];orders.innerHTML=`<table class="pf-table"><thead><tr><th>Order code</th><th>Order date</th><th>Order status</th><th>Archive status</th></tr></thead><tbody>${rows.map(o=>`<tr><td>${esc(o.order_code)}</td><td>${esc(o.order_date)}</td><td>${esc(o.status)}</td><td>${esc(o.archive_status)}</td></tr>`).join('')||'<tr><td colspan="4" class="pf-empty">No current orders found.</td></tr>'}</tbody></table>`;
 ready=true;hide.disabled=currentStatus==='active'||!archiveManaged;restore.disabled=currentStatus!=='active'||!archiveManaged;setMessage(archiveManaged?`Verified live database ${preview.database.name}; preview ${preview.diagnostic_version}. ${rows.length} current orders checked. No transaction records were changed.`:'A separate customer exclusion is already present. This archive will not overwrite or restore it; actions are disabled.','success');await loadArchiveList();}catch(e){ready=false;setMessage(`Preview unavailable: ${e.message}. Archive actions are disabled.`,'error');}}
 function openDialog(action){if(!ready||selectedId!==25)return;pendingAction=action;document.getElementById('pfCaDialogTitle').textContent=action==='activate'?'Hide Jenny Ferr’s Orders?':'Restore Jenny Ferr’s Orders?';document.getElementById('pfCaDialogText').textContent=action==='activate'?'This will hide Jenny’s orders from Admin, Manager, Staff, Customer, reports, dashboards, search, notifications, payments, inventory summaries, and order lists. It does not delete database records or change payment, inventory, file, webhook, audit, or account records. An Admin can restore them later.':'This will restore Jenny’s orders to application views. It changes only Jenny’s customer and the exact order exclusions created by this archive. Other existing Jenny order exclusions remain unchanged; no orders, payments, inventory, files, webhooks, or audit rows are edited.';dialog.showModal();}
 document.getElementById('pfCaDialogCancel').addEventListener('click',()=>dialog.close());document.getElementById('pfCaDialogConfirm').addEventListener('click',async()=>{if(!ready||!pendingAction||!archivePreviewToken)return;dialog.close();hide.disabled=true;restore.disabled=true;setMessage('Saving the reversible customer archive…');try{const result=await jsonFetch(api,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({action:pendingAction,csrf_token:csrf,preview_token:archivePreviewToken})});archivePreviewToken='';setMessage(pendingAction==='activate'?`${Number(result.orders_hidden)||0} orders hidden for ${result.customer_name||'Jenny Ferr'} (#25). Archive reference: ${result.archive_reference_id||'recorded'}.`:`Jenny Ferr’s orders are restored. Archive reference: ${result.archive_reference_id||'retained'}.`,'success');await loadPreview();}catch(e){archivePreviewToken='';setMessage(`Archive action failed: ${e.message}`,'error');await loadPreview();}});
 search.addEventListener('input',findCustomer);select.addEventListener('change',()=>{selectedId=Number(select.value)||0;if(selectedId===25)loadPreview();else{ready=false;archivePreviewToken='';hide.disabled=true;restore.disabled=true;summary.hidden=true;}});hide.addEventListener('click',()=>openDialog('activate'));restore.addEventListener('click',()=>openDialog('restore'));findCustomer();loadArchiveList();
})();
</script>
<details class="pf-archive-card"><summary style="font-weight:700;cursor:pointer">Other order archive tools</summary><p class="pf-muted">The separately maintained exact-order manifest tool remains available.</p><p><a href="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/admin/archived_orders_manifest.php">Open exact-order manifest archive</a></p></details>
